css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #F5F7F3; }
.dcx a[style*="inline-flex"]{ white-space: nowrap; }
.dcx img{ max-width: 100%; }
@media (prefers-reduced-motion: reduce){.dcx *,.dcx *::before,.dcx *::after{ animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; }
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-h1]{ font-size: 32px !important; }
.dcx [data-h2]{ font-size: 24px !important; }
}
@media (max-width: 1180px){.dcx [data-shero]{ background-position: 72% center !important; }
.dcx [data-hub]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-hub-nav]{ display: flex !important; flex-wrap: wrap; gap: 6px !important; padding: 12px !important; border-right: 0 !important; border-bottom: 1px solid rgba(16,32,26,.07); }
.dcx [data-flowmap]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-flowmap] [data-arrow]{ transform: rotate(90deg); margin: 0 auto; }
.dcx [data-matrixwrap]{ overflow-x: auto !important; }
.dcx [data-tools]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
}
@media (max-width: 720px){.dcx [data-shero]{ background-image: none !important; padding-top: 32px !important; padding-bottom: 32px !important; }
.dcx [data-shero-inner]{ max-width: none !important; }
.dcx [data-tools],.dcx [data-targets]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-row]{ grid-template-columns: minmax(0,1fr) !important; row-gap: 6px !important; }
}
